-- Moves the bundled administrative-area snapshot into a system-owned editable tree.
-- Dependencies: the System module schema, menu 2083, and zsjos_schema_version.
-- Execution order: create table, insert missing snapshot rows, add permissions, inherit grants, record version.
-- Repeatability: CREATE IF NOT EXISTS and INSERT IGNORE preserve all administrator changes on rerun.
-- Data scope: the 3,879 rows bundled in area.csv plus three area permission buttons; no rows are deleted.
-- Recovery: forward-only; disable manually added areas if rollback is required.

CREATE TABLE IF NOT EXISTS `zsjos_schema_version` (`version` varchar(64) NOT NULL, `description` varchar(255) NOT NULL, `checksum` varchar(128) DEFAULT NULL, `installed_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`version`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='ZSJOS database schema versions';

CREATE TABLE IF NOT EXISTS `system_area` (`id` int NOT NULL COMMENT 'Stable administrative area code', `name` varchar(100) NOT NULL COMMENT 'Area name', `type` tinyint NOT NULL COMMENT 'Area type: 1 country, 2 province, 3 city, 4 district', `parent_id` int NOT NULL DEFAULT 0 COMMENT 'Parent area code', `sort` int NOT NULL DEFAULT 0 COMMENT 'Display order', `status` tinyint NOT NULL DEFAULT 0 COMMENT 'Status: 0 enabled, 1 disabled', `creator` varchar(64) DEFAULT '' COMMENT 'Creator', `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Creation time', `updater` varchar(64) DEFAULT '' COMMENT 'Updater', `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Update time', `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Logical deletion flag', PRIMARY KEY (`id`), UNIQUE KEY `uk_parent_name` (`parent_id`,`name`,`deleted`), KEY `idx_parent_status_sort` (`parent_id`,`status`,`sort`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='System administrative areas';

